package com.bank.graph;

import java.util.List;
import java.util.logging.ConsoleHandler;
import java.util.logging.Formatter;
import java.util.logging.Level;
import java.util.logging.LogRecord;
import java.util.logging.Logger;

public class GraphDemo {

    private static final Logger log = Logger.getLogger(GraphDemo.class.getName());

    static {
        Logger root = Logger.getLogger("");
        for (var h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler handler = new ConsoleHandler();
        handler.setFormatter(new BankLogFormatter());
        root.addHandler(handler);
        root.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        TransferGraph graph = new TransferGraph();

        // Directed edges: who sent money to whom.
        graph.addTransfer("SAV2001", "CUR3001"); // Rajesh → Priya
        graph.addTransfer("SAV2001", "SAV4002"); // Rajesh → Amit
        graph.addTransfer("CUR3001", "SAV4002"); // Priya → Amit
        graph.addTransfer("SAV4002", "SAV2001"); // Amit → Rajesh (a cycle!)

        List<String> rajeshSentTo = graph.neighbours("SAV2001");
        log.info(() -> "SAV2001 (Rajesh) sent money to: " + rajeshSentTo);

        log.info(() -> "Total accounts (vertices): " + graph.vertexCount());
    }
}

