class TransferGraph {

    private static final Logger log = Logger.getLogger(TransferGraph.class.getName());

    // Adjacency list: account → list of accounts it sent money to.
    private final java.util.Map<String, java.util.List<String>> adjacency = new java.util.HashMap<>();

    // Add a directed edge from sender to receiver.
    void addTransfer(String from, String to) {
        adjacency.computeIfAbsent(from, k -> new java.util.ArrayList<>()).add(to);
        adjacency.computeIfAbsent(to, k -> new java.util.ArrayList<>()); // ensure vertex exists
        log.info(() -> "EDGE " + from + " -> " + to);
    }

    // Return the accounts a given account sent money to.
    java.util.List<String> neighbours(String account) {
        return adjacency.getOrDefault(account, java.util.Collections.emptyList());
    }

    int vertexCount() {
        return adjacency.size();
    }
}

// ─── Would be in config/BankLogFormatter.java in a real project ───
class BankLogFormatter extends Formatter {
    @Override
    public String format(LogRecord record) {
        return String.format("[%1$tF %1$tT] %2$-7s %3$s%n",
                new java.util.Date(record.getMillis()),
                record.getLevel().getName(),
                formatMessage(record));
    }
}
